"""Brute-force solvers for the two problems (testing only)."""

from __future__ import annotations

from itertools import product


def solve_three_coloring(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    colour = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            if all(colour[w] != c for w in adj[v]):
                colour[v] = c
                if backtrack(v + 1):
                    return True
                colour[v] = -1
        return False

    return backtrack(0)


def solve_sat(instance: dict) -> bool:
    m = instance["num_vars"]
    clauses = instance["clauses"]
    if any(len(c) == 0 for c in clauses):
        return False
    for bits in product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            if not any(
                (bits[abs(lit) - 1] if lit > 0 else not bits[abs(lit) - 1])
                for lit in clause
            ):
                ok = False
                break
        if ok:
            return True
    return False
EOF
